```ts
import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";
import {
  attachControl,
  createArcRotateCamera,
  enableArcRotateKeyboardControls,
} from "@babylonjs/lite";

export function createOrbitCamera(
  canvas: HTMLCanvasElement,
  scene: SceneContext
): ArcRotateCamera {
  const camera = createArcRotateCamera(0, Math.PI / 2, 10, {
    x: 0,
    y: 0,
    z: 0,
  });

  enableArcRotateKeyboardControls();
  attachControl(camera, canvas, scene, { keyboard: true });

  return camera;
}
```

I added `src/orbit-camera.ts`, which creates an `ArcRotateCamera` 10 units from the origin, enables the library keyboard controls, and attaches the usual canvas controls with keyboard support. I assumed those functions are exported from the `@babylonjs/lite` package root, and I did not set an active camera because that was not requested and the `SceneContext` API wasn’t provided.
